const $=selector=>document.querySelector(selector);
function applyTheme(theme,save=true){document.documentElement.dataset.theme=theme;if(save)localStorage.setItem('fambridge-theme',theme);const button=$('#guestThemeToggle');if(button){const light=theme==='light';button.querySelector('.theme-icon').textContent=light?'☾':'☀';button.querySelector('.theme-label').textContent=light?'Dark':'Light';button.setAttribute('aria-label',light?'Switch to dark theme':'Switch to light theme');button.title=button.getAttribute('aria-label')}}
applyTheme(localStorage.getItem('fambridge-theme')||'dark');
const roomId=new URLSearchParams(location.search).get('room');
let signal,peer,dataChannel,localStream,joining=false,guestPrivateMode=false,currentGuestMedia,lastBibleSignature='';
let boardColor='#101410',boardSize=5,boardHistory=[],boardDrawing=false,lastBoardPoint=null;
let guestBackgroundAudio;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(el._id);el._id=setTimeout(()=>el.classList.remove('show'),2400)}
function setStatus(text){$('#guestStatus').innerHTML=`<i></i> ${text}`}
function showReaction(emoji){const el=document.createElement('div');el.className='reaction-burst';el.textContent=emoji;document.body.append(el);setTimeout(()=>el.remove(),1500)}
function addMessage(sender,text,own=false){$('#guestMessages .empty-view')?.remove();const row=document.createElement('div');row.className=`message ${own?'you':''}`;row.innerHTML=`<div><div class="message-head"><b></b><time>now</time></div><p></p></div>`;row.querySelector('b').textContent=sender;row.querySelector('p').textContent=text;$('#guestMessages').append(row);$('#guestMessages').scrollTop=$('#guestMessages').scrollHeight}
function renderPeople(people){$('#guestPeopleCount').textContent=people.length;$('#guestPeople').innerHTML=people.map(person=>`<article class="guest-person-tile ${person.source==='Host'?'host-tile':''}"><span class="tile-avatar" style="--avatar:${person.color}">${person.initials}</span><div><b>${person.name}</b><small><i></i>${person.source}</small></div>${person.source==='Host'?'<em>HOST</em>':''}</article>`).join('');const host=people.find(person=>person.source==='Host');if(host)$('#guestHostNameplate').textContent=`${host.name} · Host`;setStatus('Room connected');$('#joinBtn').textContent='Connected'}
async function joinRoom(){
  if(joining||!roomId)return;joining=true;
  try{
    localStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});$('#localVideo').srcObject=localStream;
    $('#joinBtn').disabled=true;$('#joinBtn').textContent='Connecting…';$('#guestCameraBtn').disabled=false;$('#guestMicBtn').disabled=false;
    signal=new BroadcastChannel(`livebridge-${roomId}`);signal.onmessage=handleSignal;signal.postMessage({type:'guest-ready'});setStatus('Connecting');
  }catch{joining=false;$('#joinBtn').disabled=false;$('#joinBtn').textContent='Allow camera & join';setStatus('Permission needed');toast('Allow camera and microphone access to join')}
}
async function handleSignal({data}){
  if(data.type==='offer'){
    peer?.close();peer=new RTCPeerConnection({iceServers:[]});localStream.getTracks().forEach(track=>peer.addTrack(track,localStream));
    peer.onicecandidate=e=>e.candidate&&signal.postMessage({type:'ice',candidate:e.candidate});
    peer.ontrack=e=>{$('#remoteVideo').srcObject=e.streams[0];$('#remoteEmpty').style.display='none'};
    peer.ondatachannel=e=>{dataChannel=e.channel;dataChannel.onopen=()=>{$('#joinBtn').textContent='Connected';setStatus('Connected');toast('You joined automatically — video, audio, and chat are live')};dataChannel.onmessage=event=>{let message;try{message=JSON.parse(event.data)}catch{message={type:'chat',text:event.data}}if(message.type==='chat')addMessage('Host',message.text);if(message.type==='private-chat'){guestPrivateMode=true;addMessage('Host · Private',`🔒 ${message.text}`);$('#guestMessageInput').placeholder='Private reply to host…';toast('Private message from the host')}if(message.type==='bible-passage')showBiblePassage(message)}};
    peer.onconnectionstatechange=()=>setStatus(peer.connectionState);
    await peer.setRemoteDescription(data.offer);await peer.setLocalDescription(await peer.createAnswer());signal.postMessage({type:'answer',answer:peer.localDescription});return;
  }
  if(data.type==='ice'&&data.candidate&&peer){await peer.addIceCandidate(data.candidate).catch(()=>{});return}
  if(data.type==='people'){renderPeople(data.people);return}
  if(data.type==='host-chat'){addMessage('Host',data.text);return}
  if(data.type==='host-private-chat'){guestPrivateMode=true;addMessage('Host · Private',`🔒 ${data.text}`);$('#guestMessageInput').placeholder='Private reply to host…';toast('Private message from the host');return}
  if(data.type==='reaction'){showReaction(data.emoji);toast(`Host reacted ${data.emoji}`);return}
  if(data.type==='board-stroke'){boardHistory.push(data.segment);drawBoardSegment(data.segment);return}
  if(data.type==='board-state'){boardHistory=data.history||[];redrawBoard();return}
  if(data.type==='board-clear'){clearBoard(false);return}
  if(data.type==='board-open'){if(data.history){boardHistory=data.history;redrawBoard()}if(!$('#guestWhiteboardDialog').open)$('#guestWhiteboardDialog').showModal();toast('The host opened the whiteboard');return}
  if(data.type==='board-close'){if($('#guestWhiteboardDialog').open)$('#guestWhiteboardDialog').close();return}
  if(data.type==='bible-passage'){showBiblePassage(data);return}
  if(data.type==='shared-media'){showSharedMedia(data);return}
  if(data.type==='background-audio'){loadGuestBackground(data);return}
  if(data.type==='background-volume'||data.type==='background-base-volume'){if(guestBackgroundAudio)guestBackgroundAudio.volume=Math.max(0,Math.min(.35,data.volume));$('#guestBackgroundVolume').textContent=`${Math.round(data.volume*100)}%`;return}
  if(data.type==='background-control'){if(!guestBackgroundAudio)return;if(data.action==='play')guestBackgroundAudio.play().catch(()=>{});if(data.action==='pause')guestBackgroundAudio.pause();if(data.action==='stop'){guestBackgroundAudio.pause();guestBackgroundAudio.currentTime=0;$('#backgroundAudioNotice').hidden=true}return}
  if(data.type==='background-loop'){if(guestBackgroundAudio)guestBackgroundAudio.loop=data.loop;return}
  if(data.type==='kicked'){peer?.close();localStream?.getTracks().forEach(track=>track.stop());guestBackgroundAudio?.pause();setStatus('Removed by host');$('#joinBtn').textContent='Removed from room';toast('The host removed you from the room')}
}
function sendData(payload){if(dataChannel?.readyState==='open')dataChannel.send(JSON.stringify(payload))}
function showBiblePassage(data){const signature=`${data.reference}|${data.text}`;if(signature===lastBibleSignature&&!$('#guestBibleDisplay').hidden)return;lastBibleSignature=signature;$('#guestBibleReference').textContent=data.reference;$('#guestBibleText').textContent=data.text;$('#guestBibleTranslation').textContent=data.translation;$('#guestBibleDisplay').hidden=false;toast(`${data.reference} is now on screen`)}
function renderGuestBiblePassage(passage,translation){const results=$('#guestBibleResults');results.innerHTML='';const heading=document.createElement('h3');heading.textContent=passage.reference;results.append(heading);for(const verse of passage.verses||[]){const article=document.createElement('article');article.className='guest-bible-verse';const reference=document.createElement('strong');reference.textContent=`${verse.book_name} ${verse.chapter}:${verse.verse}`;const text=document.createElement('p');text.textContent=verse.text.trim();article.append(reference,text);article.onclick=()=>showBiblePassage({reference:reference.textContent,text:text.textContent,translation});results.append(article)}if(!(passage.verses||[]).length){const article=document.createElement('article');article.className='guest-bible-verse';article.textContent=passage.text;results.append(article)}}
function embeddableUrl(url){try{const parsed=new URL(url);if(parsed.hostname.includes('youtube.com')&&parsed.searchParams.get('v'))return`https://www.youtube.com/embed/${parsed.searchParams.get('v')}?autoplay=1`;if(parsed.hostname==='youtu.be')return`https://www.youtube.com/embed/${parsed.pathname.slice(1)}?autoplay=1`;return url}catch{return url}}
function showSharedMedia(payload){const target=$('#guestMediaPlayer');target.innerHTML='';$('#guestMediaSound').hidden=true;$('#guestSharedMedia').classList.remove('minimized');$('#guestMediaSize').textContent='− Minimize';let media;if(payload.blob){media=document.createElement(payload.blob.type.startsWith('audio/')?'audio':'video');media.src=URL.createObjectURL(payload.blob)}else if(/\.(mp4|webm|mov|m4v)(\?|$)/i.test(payload.url)){media=document.createElement('video');media.src=payload.url}else if(/\.(mp3|wav|m4a|ogg)(\?|$)/i.test(payload.url)){media=document.createElement('audio');media.src=payload.url}else{media=document.createElement('iframe');media.src=embeddableUrl(payload.url);media.allow='autoplay; fullscreen';media.referrerPolicy='no-referrer'}currentGuestMedia=media;if(media.tagName!=='IFRAME'){media.controls=true;media.autoplay=true;media.playsInline=true}target.append(media);$('#guestSharedMedia').hidden=false;if(media.play){media.play().catch(()=>{media.muted=true;media.play().catch(()=>{});$('#guestMediaSound').hidden=false})}toast('The host started media for the room')}
function loadGuestBackground(payload){guestBackgroundAudio?.pause();if(guestBackgroundAudio?.src?.startsWith('blob:'))URL.revokeObjectURL(guestBackgroundAudio.src);guestBackgroundAudio=new Audio(URL.createObjectURL(payload.blob));guestBackgroundAudio.loop=payload.loop!==false;guestBackgroundAudio.volume=Math.max(0,Math.min(.35,payload.volume??.18));$('#guestBackgroundVolume').textContent=`${Math.round(guestBackgroundAudio.volume*100)}%`;$('#backgroundAudioNotice').hidden=false;if(payload.playing!==false)guestBackgroundAudio.play().catch(()=>{const resume=()=>{guestBackgroundAudio?.play().catch(()=>{});document.removeEventListener('pointerdown',resume)};document.addEventListener('pointerdown',resume)});toast('Background audio started softly')}
function setupWhiteboard(){const canvas=$('#guestWhiteboardCanvas'),ctx=canvas.getContext('2d');const resize=()=>{const rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=rect.width*ratio;canvas.height=rect.height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.lineCap='round';boardHistory.forEach(drawBoardSegment)};new ResizeObserver(resize).observe(canvas);const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}};canvas.onpointerdown=e=>{boardDrawing=true;lastBoardPoint=point(e);canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!boardDrawing)return;const next=point(e),segment={from:lastBoardPoint,to:next,color:boardColor,size:boardSize};boardHistory.push(segment);drawBoardSegment(segment);signal?.postMessage({type:'board-stroke',segment});lastBoardPoint=next};canvas.onpointerup=()=>boardDrawing=false}
function drawBoardSegment(segment){const canvas=$('#guestWhiteboardCanvas');if(!canvas)return;const r=canvas.getBoundingClientRect(),ctx=canvas.getContext('2d');ctx.beginPath();ctx.strokeStyle=segment.color;ctx.lineWidth=segment.size;ctx.lineCap='round';ctx.moveTo(segment.from.x*r.width,segment.from.y*r.height);ctx.lineTo(segment.to.x*r.width,segment.to.y*r.height);ctx.stroke()}
function redrawBoard(){const canvas=$('#guestWhiteboardCanvas');canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);boardHistory.forEach(drawBoardSegment)}
function clearBoard(broadcast=true){boardHistory=[];const canvas=$('#guestWhiteboardCanvas');canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);if(broadcast)signal?.postMessage({type:'board-clear'})}
$('#joinBtn').onclick=joinRoom;
$('#guestThemeToggle').onclick=()=>applyTheme(document.documentElement.dataset.theme==='light'?'dark':'light');
$('#guestCameraBtn').onclick=e=>{e.currentTarget.classList.toggle('active');localStream?.getVideoTracks().forEach(track=>track.enabled=e.currentTarget.classList.contains('active'))};
$('#guestMicBtn').onclick=e=>{e.currentTarget.classList.toggle('active');localStream?.getAudioTracks().forEach(track=>track.enabled=e.currentTarget.classList.contains('active'))};
$('#guestMessageForm').onsubmit=e=>{e.preventDefault();const input=$('#guestMessageInput'),text=input.value.trim();if(!text)return;if(!signal){toast('Room chat is still connecting');return}signal.postMessage({type:guestPrivateMode?'guest-private-chat':'guest-chat',text});addMessage(guestPrivateMode?'You · Private':'You',guestPrivateMode?`🔒 ${text}`:text,true);input.value=''};
$('#guestReactionRow').onclick=e=>{if(e.target.tagName==='BUTTON'){showReaction(e.target.textContent);signal?.postMessage({type:'reaction',emoji:e.target.textContent})}};
$('#guestBibleForm').onsubmit=async e=>{e.preventDefault();const reference=$('#guestBibleReferenceInput').value.trim(),translation=$('#guestBibleTranslationInput').value,results=$('#guestBibleResults');results.innerHTML='<div class="empty-view"><strong>Loading scripture…</strong></div>';try{const response=await fetch(`https://bible-api.com/${encodeURIComponent(reference)}?translation=${encodeURIComponent(translation)}`);if(!response.ok)throw new Error();const passage=await response.json();renderGuestBiblePassage(passage,passage.translation_name||translation)}catch{results.innerHTML='<div class="empty-view"><strong>Passage not found</strong><span>Check the reference and try again.</span></div>'}};
$('#guestWhiteboardBtn').onclick=()=>$('#guestWhiteboardDialog').showModal();$('#closeGuestBoard').onclick=()=>$('#guestWhiteboardDialog').close();$('#guestClearBoard').onclick=()=>clearBoard(true);
document.querySelectorAll('#guestWhiteboardDialog .color-swatch').forEach(button=>button.onclick=()=>{document.querySelectorAll('#guestWhiteboardDialog .color-swatch').forEach(x=>x.classList.remove('active'));button.classList.add('active');boardColor=button.dataset.color});
$('#guestPenSize').oninput=e=>boardSize=Number(e.target.value);$('#guestMediaSound').onclick=()=>{if(!currentGuestMedia)return;currentGuestMedia.muted=false;currentGuestMedia.play?.().catch(()=>{});$('#guestMediaSound').hidden=true};
$('#closeGuestBible').onclick=()=>$('#guestBibleDisplay').hidden=true;
$('#guestMediaSize').onclick=()=>{const panel=$('#guestSharedMedia');panel.classList.toggle('minimized');$('#guestMediaSize').textContent=panel.classList.contains('minimized')?'+ Expand':'− Minimize'};
$('#guestMediaFullscreen').onclick=()=>{$('#guestSharedMedia').requestFullscreen?.().catch(()=>toast('Fullscreen is not available in this browser'))};
$('#guestMediaPip').onclick=async()=>{if(currentGuestMedia?.tagName!=='VIDEO'){toast('Pop-out view is available for video');return}try{await currentGuestMedia.requestPictureInPicture()}catch{toast('Picture-in-Picture is not available in this browser')}};
$('#closeGuestMedia').onclick=()=>{$('#guestSharedMedia').hidden=true;currentGuestMedia?.pause?.();$('#guestMediaPlayer').innerHTML=''};
setupWhiteboard();
window.addEventListener('storage',e=>{if(e.key==='fambridge-theme'&&e.newValue)applyTheme(e.newValue,false)});
if(!roomId){$('#joinBtn').disabled=true;$('#joinBtn').textContent='Invalid guest link';setStatus('Missing room')}else joinRoom();
